() => {
  const cb = document.querySelector('input[type="checkbox"]');
  if (cb) { cb.click(); return 'clicked'; }
  return 'no checkbox found';
}

() => {
  const cb = document.querySelector('input[type="checkbox"]');
  if (cb) { 
    cb.click(); 
    return { clicked: true, checked: cb.checked }; 
  }
  return 'no checkbox found';
}

() => {
  const cb = document.querySelector('input[type="checkbox"]');
  if (cb) { 
    cb.click(); 
    return { clicked: true, checked: cb.checked, classes: cb.className }; 
  }
  return 'no checkbox found';
}

() => {
  const cb = document.querySelector('input[type="checkbox"]');
  if (cb) { 
    const rect = cb.getBoundingClientRect();
    cb.focus();
    cb.click();
    // Trigger the click on the wrapper too
    const wrapper = cb.closest('div');
    if (wrapper) wrapper.click();
    return { 
      clicked: true, 
      checked: cb.checked, 
      visible: rect.width > 0 && rect.height > 0,
      rect: { x: rect.x, y: rect.y, w: rect.width, h: rect.height }
    }; 
  }
  return 'no checkbox found';
}

() => {
  const cb = document.querySelector('input[type="checkbox"]');
  if (!cb) return 'no checkbox';

  // Try multiple ways to trigger the checkbox
  const rect = cb.getBoundingClientRect();
  const x = rect.x + rect.width/2;
  const y = rect.y + rect.height/2;

  // Synthesize a complete mouse event sequence
  ['mousedown', 'mouseup', 'click'].forEach(type => {
    cb.dispatchEvent(new MouseEvent(type, {bubbles: true, cancelable: true, view: window, clientX: x, clientY: y}));
  });

  return { 
    checked: cb.checked, 
    rect: { x: rect.x, y: rect.y, w: rect.width, h: rect.height },
    visible: rect.width > 0 && rect.height > 0
  };
}

() => {
  const iframes = document.querySelectorAll('iframe');
  return Array.from(iframes).map(f => ({
    src: f.src,
    id: f.id,
    name: f.name,
    title: f.title
  }));
}

() => {
  // Look for Turnstile elements
  const turnstile = document.querySelector('[id*="turnstile"], [class*="turnstile"], [id*="cf-chl"], [class*="cf-chl"]');
  const iframes = document.querySelectorAll('iframe');

  const iframeData = Array.from(iframes).map(f => ({
    src: f.src,
    id: f.id,
    name: f.name,
    title: f.title,
    visible: f.getBoundingClientRect().width > 0
  }));

  return {
    turnstile: turnstile ? turnstile.outerHTML.substring(0, 200) : null,
    iframes: iframeData,
    allElements: Array.from(document.querySelectorAll('div')).filter(d => d.getBoundingClientRect().width > 100 && d.getBoundingClientRect().height > 30).map(d => ({
      tag: d.tagName,
      id: d.id,
      classes: d.className.substring(0, 100),
      rect: { x: d.getBoundingClientRect().x, y: d.getBoundingClientRect().y, w: d.getBoundingClientRect().width, h: d.getBoundingClientRect().height }
    })).slice(0, 5)
  };
}

() => {
  const cb = document.querySelector('input[type="checkbox"]');
  if (!cb) return 'no checkbox';

  // Get the visible wrapper - it should be in a div above the input
  const wrapper = cb.closest('[id*="cf"], [class*="cf"], div');

  // Dispatch native click events
  const evt = new MouseEvent('click', {
    bubbles: true,
    cancelable: true,
    view: window,
    button: 0
  });

  cb.dispatchEvent(evt);

  // Also try setting checked
  cb.checked = true;
  cb.dispatchEvent(new Event('change', { bubbles: true }));

  return { checked: cb.checked };
}

async () => {
  const cb = document.querySelector('input[type="checkbox"]');
  if (!cb) return 'no checkbox';

  const rect = cb.getBoundingClientRect();
  const x = rect.x + rect.width/2;
  const y = rect.y + rect.height/2;

  // Create a sequence of events as if from a real mouse
  const events = ['mouseover', 'mousedown', 'mouseup', 'click'];

  for (const type of events) {
    const event = new MouseEvent(type, {
      bubbles: true,
      cancelable: true,
      composed: true,
      view: window,
      button: 0,
      buttons: type === 'mousedown' ? 1 : 0,
      clientX: x,
      clientY: y,
      screenX: x,
      screenY: y
    });
    cb.dispatchEvent(event);
    await new Promise(r => setTimeout(r, 50));
  }

  return { 
    checked: cb.checked,
    rect: { x, y, w: rect.width, h: rect.height }
  };
}

() => {
  // Try clicking the wrapper div containing the checkbox
  const cb = document.querySelector('input[type="checkbox"]');
  if (!cb) return 'no checkbox';

  // The actual interactive area might be the parent div
  let parent = cb.parentElement;
  while (parent && parent !== document.body) {
    const rect = parent.getBoundingClientRect();
    if (rect.width > 100 && rect.height > 30 && rect.width < 500 && rect.height < 200) {
      // Simulate a real click at the center
      const x = rect.x + rect.width/2;
      const y = rect.y + rect.height/2;

      parent.dispatchEvent(new MouseEvent('pointerdown', {bubbles: true, cancelable: true, view: window, clientX: x, clientY: y, button: 0}));
      parent.dispatchEvent(new MouseEvent('mousedown', {bubbles: true, cancelable: true, view: window, clientX: x, clientY: y, button: 0}));
      parent.dispatchEvent(new MouseEvent('pointerup', {bubbles: true, cancelable: true, view: window, clientX: x, clientY: y, button: 0}));
      parent.dispatchEvent(new MouseEvent('mouseup', {bubbles: true, cancelable: true, view: window, clientX: x, clientY: y, button: 0}));
      parent.dispatchEvent(new MouseEvent('click', {bubbles: true, cancelable: true, view: window, clientX: x, clientY: y, button: 0}));

      return { clicked: parent.outerHTML.substring(0, 100), checked: cb.checked };
    }
    parent = parent.parentElement;
  }
  return 'no suitable parent found';
}

() => {
  // The interactive part may be the visible div surrounding the checkbox
  const checkboxLabel = document.querySelector('[aria-label="请验证您是真人"]');
  if (!checkboxLabel) return 'no checkbox label';

  // Get the parent div which is the visual widget
  const widget = checkboxLabel.closest('div');

  // Find the actual widget container
  let actualWidget = checkboxLabel;
  while (actualWidget && actualWidget.tagName !== 'BODY') {
    const rect = actualWidget.getBoundingClientRect();
    if (rect.width >= 200 && rect.height >= 50) {
      break;
    }
    actualWidget = actualWidget.parentElement;
  }

  if (!actualWidget || actualWidget.tagName === 'BODY') {
    actualWidget = widget;
  }

  const rect = actualWidget.getBoundingClientRect();

  // Click center
  const x = rect.x + rect.width / 2;
  const y = rect.y + rect.height / 2;

  // Use Element.click() method first
  checkboxLabel.click();

  return { 
    success: true, 
    rect: { x, y, w: rect.width, h: rect.height },
    html: actualWidget.outerHTML.substring(0, 200)
  };
}
